// 解析 Local Agent 发送的组合数据（兼容 publish_to_n8n.py 的 payload）
const body = $input.item.json.body || $input.item.json;
let images = body.images || [];
if (typeof images === 'string') images = images.split(',').map(s => s.trim()).filter(Boolean);
let tags = body.tags || [];
if (typeof tags === 'string') tags = tags.split(',').map(s => s.trim()).filter(Boolean);
return [{
  json: {
    title: body.title || '无标题',
    xhs_content: body.xhs_content || body.content || '',
    gzh_html: body.gzh_html || '',
    images: images,
    tags: tags
  }
}];

// 分支 1：小红书自动发布 → xhs-publisher 微服务（Playwright）
// 指数退避重试 3 次（1s/2s），失败不抛异常、返回 ok:false，不阻塞公众号分支
const data = $input.first().json;
const payload = {
  title: data.title,
  content: data.xhs_content,
  images: data.images,
  tags: data.tags,
  cookies_json_path: '/data/shared/xhs_cookies.json'
};
for (let i = 0; i < 3; i++) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://xhs-publisher:8000/publish',
      json: payload,
      timeout: 120000
    });
    return [{ json: { ok: true, res } }];
  } catch (e) {
    if (i === 2) return [{ json: { ok: false, error: e.message } }];
    await new Promise(r => setTimeout(r, 1000 * Math.pow(2, i)));
  }
}

// 分支 2：公众号草稿 → xhs-publisher 微服务 /publish/gzh（存草稿，人工确认发布）
// 指数退避重试 3 次，失败不抛异常、返回 ok:false
const data = $input.first().json;
const payload = {
  title: data.title,
  content: data.gzh_html || data.xhs_content || '',
  images: [],
  tags: [],
  cookies_json_path: '/data/shared/gzh_cookies.json'
};
for (let i = 0; i < 3; i++) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://xhs-publisher:8000/publish/gzh',
      json: payload,
      timeout: 120000
    });
    return [{ json: { ok: true, res } }];
  } catch (e) {
    if (i === 2) return [{ json: { ok: false, error: e.message } }];
    await new Promise(r => setTimeout(r, 1000 * Math.pow(2, i)));
  }
}

// 汇总两分支结果（任一平台失败不阻塞其他平台）
const read = (name) => {
  try {
    return $('' + name).all().map(i => i.json)[0] || {};
  } catch (e) { return {}; }
};
const xhs = read('分支 1：小红书自动发布 (Playwright)');
const gzh = read('分支 2：公众号草稿 (Playwright)');
return [{
  json: {
    status: 'success',
    message: '🎉 双平台发布流程已执行完成（详见各平台结果）',
    xhs: xhs.ok ? '✅ 小红书发布成功' : ('⚠️ 小红书: ' + (xhs.error || JSON.stringify(xhs).slice(0, 200))),
    gzh: gzh.ok ? '✅ 公众号草稿已保存（待人工确认发布）' : ('⚠️ 公众号: ' + (gzh.error || JSON.stringify(gzh).slice(0, 200))),
    published_at: new Date().toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' })
  }
}];
